-- Sync CMS content to an already-seeded database. Safe to re-run.
-- Run in Supabase → SQL Editor after editing src/content/seed.ts.
begin;

-- Philosophy long-form columns on elements (added once; no-op if present)
alter table public.elements
  add column if not exists subtitle text,
  add column if not exists lead text,
  add column if not exists principle text,
  add column if not exists in_design text,
  add column if not exists story_label text,
  add column if not exists story_text text,
  add column if not exists visual_language text;

update public.site_settings set seo_title = 'Home Furnishings & Interiors in Patna | New Ankur Furnishers', seo_description = 'Patna''s trusted home furnishing house since 1984. Curtains, blinds, flooring, wallpaper, mattresses, rugs and furniture — measured and fitted by our own team, for homes and businesses alike.', tagline = 'Your Home, Your Story!' where id = 1;

update public.elements set name = 'Earth', sanskrit = 'Prithvi', tagline = 'What holds you', description = 'Grounding materials underfoot and around you: floors of wood and stone-like vinyl, rugs that soften a room, and furniture built to stay.', image_url = '/images/elements/earth.webp', image_alt = 'Earthy room with a stone sculpture, terracotta leather sofa and an autumn tree', subtitle = 'Foundation, Craft, Permanence', lead = null, principle = 'Earth grounds us — materiality, authenticity, the honest expression of wood, stone, clay and natural fibre.', in_design = 'Visible joinery. Tactile surfaces. Furniture that reveals its construction. Textiles that age beautifully.', story_label = 'The craft story', story_text = 'Our mastery lies in understanding materials deeply — how wood moves, how leather develops a patina, how upholstery holds its form across decades. This is not mass production. It is stewardship.', visual_language = 'Warm ochre, terracotta and deep browns. Textures that invite touch. Compositions that feel rooted and stable.' where slug = 'earth';
update public.elements set name = 'Water', sanskrit = 'Jal', tagline = 'What restores you', description = 'Rest and renewal: mattresses, bed linen and bath textiles chosen for softness, freshness and a good night''s sleep.', image_url = '/images/elements/water.webp', image_alt = 'Seaside setting with a glass table, sheer glassware and the ocean beyond', subtitle = 'Flow, Adaptability, Softness', lead = null, principle = 'Water flows and adapts to its container — gentle and powerful. In living spaces: flexibility, comfort, the softness that makes a house a home.', in_design = 'Curved forms. Layered textiles. Upholstery that invites you to sink in. Lighting that shifts through the day.', story_label = 'The comfort story', story_text = 'Luxury is not hardness or severity. It is the moment you sit into a perfectly proportioned sofa, the weight of a linen curtain, the temperature of a room at dusk.', visual_language = 'Soft blues, greens and greys. Flowing lines. Generous proportions. Spaces that breathe.' where slug = 'water';
update public.elements set name = 'Fire', sanskrit = 'Agni', tagline = 'What warms you', description = 'Warmth and glow: lighting, rich upholstery and the decorative accents that give a room its personality.', image_url = '/images/elements/fire.webp', image_alt = 'Coral arched alcove with a fire and a cream curved sofa', subtitle = 'Warmth, Character, Energy', lead = null, principle = 'Fire brings warmth and character — the spark of personality in a space. Without it, even the most beautiful room feels cold.', in_design = 'Accent colours that surprise. Lighting that creates drama and intimacy. Materials with depth — velvet, brass, dark wood. Compositions with a point of view.', story_label = 'The personality story', story_text = 'A space should reflect the people who live in it. Our role is to provide the palette, the forms and the materials — tools that let you express your own warmth. We design for living, not for magazines.', visual_language = 'Deep jewel tones. Warm metallics. Dramatic contrasts. Moments of unexpected richness.' where slug = 'fire';
update public.elements set name = 'Air', sanskrit = 'Vayu', tagline = 'What lets you breathe', description = 'Light and air in balance: sheer and blackout curtains, blinds and motorised window systems that shape how a room feels through the day.', image_url = '/images/elements/air.webp', image_alt = 'Soft pink and blue scene with clouds, an arch and a boucle stool', subtitle = 'Light, Openness, Freedom', lead = 'Luxury today is not about abundance — it is about clarity. Every piece in a space should earn its place.', principle = 'Air is invisible but essential: the space between objects, the light that defines form, the freedom to move and breathe.', in_design = 'Generous spacing. Minimal visual clutter. Furniture scaled to human proportion. Negative space as a design element.', story_label = null, story_text = null, visual_language = 'Light, neutral backgrounds. Breathing room. Clarity of form. Simplicity that reveals complexity.' where slug = 'air';
update public.elements set name = 'Space', sanskrit = 'Akasha', tagline = 'What surrounds you', description = 'The envelope of a room: wallpapers, wall panelling, glass films and the finishes that define the space itself.', image_url = '/images/elements/space.webp', image_alt = 'Beige fluted arch with a palm, a coral disc and a terracotta shell chair', subtitle = 'Architecture, Possibility, Balance', lead = null, principle = 'Space is the container — the fifth element that holds all others in balance. Architecture and interior design are inseparable.', in_design = 'Furniture as architecture. Spatial planning that considers sightlines, acoustics and movement. Collections that work as a system, not isolated pieces.', story_label = 'Systems thinking', story_text = 'We do not design individual products; we design environments. A sofa is never separate from the wall behind it, the light above it, the rug beneath it. Every element is in conversation.', visual_language = 'Architectural clarity. Balanced compositions. Spatial depth. Harmony across scales.' where slug = 'space';

update public.sectors set name = 'Home Furnishings', tagline = 'Where every corner tells a story.', summary = 'Curtains, flooring, furniture, bedding and wall finishes — everything your home needs, chosen with you and fitted by our own team.', highlights = '[{"title":"Curtains & blinds","text":"Blackout, sheer and motorised options, measured and fitted at your doorstep."},{"title":"Flooring","text":"Wooden, herringbone, SPC and vinyl floors, installed quickly and cleanly."},{"title":"Bedroom","text":"Mattresses, bed-backs, linen and duvets, chosen for better rest."},{"title":"Walls","text":"Wallpaper, murals and panelling to set the tone of a room."}]'::jsonb where slug = 'home';
update public.sectors set name = 'Hotels & Restaurants', tagline = 'Hospitality that feels effortless.', summary = 'Carpets, linen, curtains and furnishings for hotels, restaurants and banquet halls — hotel-grade, hard-wearing and installed on schedule.', highlights = '[{"title":"Wall-to-wall carpets","text":"Designer and corporate patterns for banquets, lobbies, suites and boardrooms."},{"title":"Room linen","text":"Bedsheets, duvets, mattress protectors and bath linen in hotel grades."},{"title":"Table linen","text":"Linens and overlays that dress up every event."},{"title":"Window solutions","text":"Blackout curtains and blinds for restful guest rooms."}]'::jsonb where slug = 'hospitality';
update public.sectors set name = 'Healthcare', tagline = 'Hygienic, hard-wearing, humane.', summary = 'Flooring, curtains, mattresses and wallcoverings built for hospitals and clinics — specified for hygiene and durability, supplied and fitted end to end.', highlights = '[{"title":"Healthcare flooring","text":"Homogeneous, conductive and heterogeneous PVC flooring for ICU, OPD and more."},{"title":"Hospital curtains & tracks","text":"Quick, easy installation at your doorstep."},{"title":"Hospital mattresses & pillows","text":"Made to your dimensions and requirements."},{"title":"Anti-bacterial wallpapers","text":"Wallcoverings made for healthcare settings."},{"title":"Window solutions","text":"Vertical, roller and sheer dimout blinds."},{"title":"Hygienic mats","text":"Exterior, interior, anti-skid and bath mats."},{"title":"Bedsheets & blankets","text":"Durable, comfortable options for patient care."},{"title":"Glass films","text":"Heat control and privacy for plain glass surfaces."}]'::jsonb where slug = 'healthcare';
update public.sectors set name = 'Institutions & Education', tagline = 'Spaces that help learning happen.', summary = 'Flooring, blinds, wallcoverings and sports surfaces for schools, colleges and coaching institutes — practical, durable and easy to maintain.', highlights = '[{"title":"Flooring","text":"Classroom and gym flooring, carpets and carpet tiles for auditoriums and cabins."},{"title":"Sports flooring","text":"For playing areas, tennis and badminton courts."},{"title":"Window solutions","text":"Room-darkening, light-filtering and acoustic blinds."},{"title":"Wallcoverings","text":"From budget-friendly to niche, plus digital murals for play areas and libraries."},{"title":"Wall panelling","text":"For smart classes and music rooms."},{"title":"Green turf & green walls","text":"For aesthetics and everyday use."},{"title":"Glass films","text":"Frosted, reflective, printed and PVC."},{"title":"Heat insulation & gifting","text":"Roofing insulation and corporate gifting for institutions."}]'::jsonb where slug = 'education';
update public.sectors set name = 'Office & Industrial', tagline = 'Workspaces that work harder.', summary = 'Carpet tiles, blinds, glass films and specialist flooring for offices and industrial spaces — quiet underfoot, hard-wearing and glare-free.', highlights = '[{"title":"Carpet tiles","text":"Hard-wearing, easy to replace, quiet underfoot."},{"title":"Blinds","text":"Roller and vertical blinds for glare-free work."},{"title":"Glass films","text":"Privacy and branding for cabins and partitions."},{"title":"Anti-static & PVC stud flooring","text":"For server rooms, ramps, parking and entrances."}]'::jsonb where slug = 'office';
update public.sectors set name = 'Art & Decor', tagline = 'The details that make a room yours.', summary = 'Lighting, cushions, runners and accent furniture — the finishing touches that give a space its character.', highlights = '[{"title":"Lighting","text":"Fabric lamps and statement pieces for serene spaces."},{"title":"Cushions & runners","text":"A pop of colour and texture for sofas and beds."},{"title":"Accent furniture","text":"Consoles, tea tables and carved wooden partitions (jharokhas)."}]'::jsonb where slug = 'art-decor';

update public.categories set name = 'Mattresses', tagline = 'Rest, made to measure', intro = 'Spring, foam and coir mattresses chosen for how you actually sleep — including hospital mattresses made to your exact dimensions. Supportive, comfortable and built to last.', subtypes = array['Spring mattresses','Foam mattresses','Coir mattresses','Hospital mattresses','Mattress protectors']::text[] where slug = 'mattresses';
update public.categories set name = 'Pillows & Bedding', tagline = 'Dressed for a good night', intro = 'Pillows, bedsheets, duvets and covers in every size and thread count — from easy everyday cotton to soft premium weaves for the whole family.', subtypes = array['Pillows & cushions','Bedsheets','Duvets & duvet covers','Mattress protectors','Bed runners']::text[] where slug = 'pillows-bedding';
update public.categories set name = 'Bath Linen & Mats', tagline = 'Soft, absorbent, everyday', intro = 'Bath, hand, pool and face towels with quick-dry twist technology, plus anti-slip, water-absorbent bath mats — for homes, hotels and poolsides.', subtypes = array['Bath towels','Hand & face towels','Pool towels','Bath mats','Exterior mats']::text[] where slug = 'bath-linen';
update public.categories set name = 'Curtains & Upholstery', tagline = 'The right light, beautifully framed', intro = 'Blackout and sheer curtains for privacy and light control, upholstery fabrics in every colour, and the rods and tracks to finish them — measured and fitted at your doorstep.', subtypes = array['Blackout curtains','Sheer curtains','Hospital curtains & tracks','Upholstery fabrics','Exterior-grade fabrics & leatherette','Curtain rods & accessories']::text[] where slug = 'curtains-upholstery';
update public.categories set name = 'Blinds', tagline = 'Light, exactly how you want it', intro = 'Roller, sheer dimout, vertical and wooden venetian blinds — including room-darkening and acoustic options for homes, offices and institutions.', subtypes = array['Roller blinds','Sheer dimout blinds','Vertical blinds','Wooden venetian blinds','Acoustic blinds']::text[] where slug = 'blinds';
update public.categories set name = 'Floorings', tagline = 'A floor that lasts for years', intro = 'Wooden, engineered, herringbone, SPC and vinyl floors — plus healthcare and sports flooring — engineered for quick installation, minimal wastage and a seamless finish.', subtypes = array['Wooden flooring','Engineered wood','Herringbone & fishbone','SPC flooring','PVC / vinyl flooring','Healthcare PVC flooring','Sports & gym flooring','Anti-static flooring']::text[] where slug = 'floorings';
update public.categories set name = 'Wallpapers & Panelling', tagline = 'Walls with real character', intro = 'Designer and custom digital wallpapers, murals and wall panelling — from budget-friendly to bespoke, including anti-bacterial papers for healthcare settings.', subtypes = array['Designer wallpapers','Custom murals','Anti-bacterial wallpapers','Wall panelling','Bed-backs']::text[] where slug = 'wallpapers';
update public.categories set name = 'Furniture', tagline = 'Made to live with', intro = 'Sofas, chairs, ottomans, bespoke bed-backs and fine wooden pieces — crafted for comfort and made to your preference, by a team that understands materials.', subtypes = array['Sofas & couches','Chairs & ottomans','Bed-backs (fabric & leatherette)','Wooden furniture','Consoles & tea tables','Partitions (jharokhas)']::text[] where slug = 'furniture';
update public.categories set name = 'Landscaping & Outdoor', tagline = 'Bring the outdoors in', intro = 'UV-treated artificial grass in multiple pile heights, green walls, weatherproof decking and awnings — for balconies, terraces and gardens.', subtypes = array['Artificial grass','Green walls','Decking','Fixed & retractable awnings']::text[] where slug = 'landscaping';
update public.categories set name = 'Home Decor & Lighting', tagline = 'The finishing touch', intro = 'Fabric lamps, cushion covers, bed runners, table linen and decorative accents — the small, considered details that give a room its personality.', subtypes = array['Fabric lamps','Cushion covers & bed runners','Table linen & overlays','Decor accents']::text[] where slug = 'home-decor';
update public.categories set name = 'Rugs & Carpets', tagline = 'Warmth underfoot', intro = 'Rugs in standard and custom sizes, plus wall-to-wall carpets in designer and corporate patterns for banquets, lobbies and boardrooms.', subtypes = array['Custom rugs','Regular rugs','Wall-to-wall carpets','Carpet tiles']::text[] where slug = 'rugs-carpets';
update public.categories set name = 'Glass Films', tagline = 'Privacy, with a view', intro = 'Frosted, reflective, printed and PVC films that bring privacy, heat control and design to any glass surface — for offices, clinics and homes.', subtypes = array['Frosted films','Reflective films','Printed / designer films','Heat control films']::text[] where slug = 'glass-films';
update public.categories set name = 'Home Automation', tagline = 'Comfort at a touch', intro = 'Motorised curtains and blinds with smart-home control, so light and privacy are a tap — or a voice command — away.', subtypes = array['Motorised curtains','Motorised blinds','Smart home control']::text[] where slug = 'home-automation';
update public.categories set name = 'Gym Mats & Specialty', tagline = 'Built to work hard', intro = 'Rubber and gym mats, PVC stud flooring for ramps and parking, floor protectors and heat insulation — practical surfaces for demanding spaces.', subtypes = array['Rubber & gym mats','PVC stud flooring','Floor protectors','Heat insulation','Bubble wraps']::text[] where slug = 'specialty-solutions';

insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'hero', 'Home: hero', 'Patna · Since 1984', 'Your home, your story.', 'Curtains, floors, walls and furniture — chosen with you and fitted by our own team, the way we''ve furnished homes and businesses across Patna for over forty years.', '/images/brochure/hero-bedroom.webp', 'Sunlit bedroom with a rust velvet bed and sheer curtains', 'Explore products', '/products', '[]'::jsonb, 1) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'story', 'Home: story strip', 'Since 1984', 'Furnishing relationships, not just rooms.', 'What began in 1984 as a furnishing shop on S.P. Verma Road now dresses homes, hotels, hospitals, schools and offices across Bihar — from the first measurement to the final fitting.', null, null, null, null, '[]'::jsonb, 2) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'philosophy', 'Home: philosophy teaser', 'Our philosophy', 'Every home is made of five elements.', 'Earth, water, fire, air and space — the five elements we furnish, so a room feels not just finished, but in balance.', null, null, 'Explore the philosophy', '/philosophy', '[]'::jsonb, 3) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'categories', 'Home: categories heading', 'What we do', 'Everything your space needs, in one place.', null, null, null, 'Browse all products', '/products', '[]'::jsonb, 4) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'sectors', 'Home: sectors heading', 'Where we work', 'From quiet homes to busy hospitals.', 'The same care and craft, scaled to the space.', null, null, 'See our expertise', '/expertise', '[]'::jsonb, 5) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'cta', 'Home: enquiry banner', null, 'Let''s bring your space to life.', 'Tell us what you''re planning. We''ll visit, measure and suggest options that suit your space and your budget.', '/images/brochure/why-dining.webp', 'Dining corner with ceramic pendant lamps', 'Make an enquiry', '/contact', '[]'::jsonb, 6) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'intro', 'About: introduction', 'About us', 'Furnishing homes and businesses since 1984.', 'New Ankur Furnishers began as a furnishing shop in the heart of Patna, and has spent four decades doing one thing well: helping people create spaces that feel like home.

From living rooms to hotels, hospitals to offices, we bring the same eye for materials and the same care in fitting — so every space we touch feels considered, comfortable and built to last.', '/images/brochure/about-armchair.webp', 'Teal armchair with a blush cushion beside a side table', null, null, '[]'::jsonb, 1) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'why', 'About: why choose us', null, 'Why choose us', null, '/images/brochure/why-dining.webp', 'Dining corner with ceramic pendant lamps', null, null, '[{"title":"Four decades of experience","text":"Furnishing homes and businesses across Bihar since 1984."},{"title":"Fitted by our own team","text":"From measurement to installation, handled start to finish — no loose ends."},{"title":"Materials you can trust","text":"Honest, hard-wearing materials chosen to last, not just to look good on day one."},{"title":"Priced for real budgets","text":"Options at every price point, with honest advice on what''s worth it."}]'::jsonb, 2) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'founder', 'About: founder''s note', 'From our founder', 'Forty years of furnishing relationships.', 'For us, a home is not just a place but a feeling — where the presence of loved ones becomes comfort, where relationships breathe, and where dreams take shape.

For over forty years, New Ankur Furnishers has tried to fill every home with warmth, belonging and memory, so that your home doesn''t only look beautiful but becomes a part of your story.

Your trust and your affection are our greatest strength. Come, let us shape the home you have in mind, together.', '/images/brochure/sector-home.webp', 'Bright living room with panelled walls', 'Santosh Kumar Agrawal', null, '[]'::jsonb, 3) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'heritage', 'About: heritage intro', 'Our story', 'Rooted in Patna, since 1984.', 'In 1984, we set out with a singular conviction: that a home is not furnished with objects, but with memories, textures and enduring grace.', '/images/brochure/wooden-furniture.webp', 'Master craftsman and apprentice at the workbench', 'Santosh Kumar Agrawal', null, '[]'::jsonb, 4) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'pillars', 'About: what we stand for + timeline', null, 'What we stand for.', 'From a single shop on S.P. Verma Road, New Ankur Furnishers has grown into a trusted name for furnishings and interiors across Patna and Bihar — for homes, hotels, hospitals, offices and institutions.', null, null, null, null, '[{"title":"1984 — Where it began","text":"New Ankur Furnishers opened on S.P. Verma Road in Patna, with a simple belief: honest materials, measured well and fitted properly."},{"title":"Over the years — Beyond the home","text":"The same craft grew from living rooms to hotels, hospitals, schools and offices across Bihar."},{"title":"Today — Start to finish","text":"From the first site visit and measurement to the final fitting, every project is handled end to end by our own team."}]'::jsonb, 5) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'concierge', 'About: consultation CTA', 'Visit or get in touch', 'Planning a project? Let''s start with a conversation.', null, null, null, 'Make an enquiry', '/contact', '[]'::jsonb, 6) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('philosophy', 'intro', 'Philosophy: intro', 'The brand idea', 'Five Elements of Nature', 'Rooted in Indian philosophy and design tradition, the five elements are our organizing intelligence — a lens for every material we choose, every proportion we draw and every room we compose.', null, null, null, null, '[]'::jsonb, 1) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('philosophy', 'framework', 'Philosophy: framework cards', null, null, null, null, null, null, null, '[{"title":"A timeless framework","text":"Rooted in Indian philosophy and design tradition. Each element is a principle of balance, harmony and human flourishing — not a material or an aesthetic."},{"title":"A complete philosophy","text":"Together, the five elements form a coherent lens through which every design decision, every material choice and every spatial composition is made."},{"title":"Not a gimmick","text":"This is how we think, how we create, how we live. It is the organizing intelligence of everything we do."}]'::jsonb, 2) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('expertise', 'intro', 'Expertise: intro', 'Where we work', 'From quiet homes to busy hospitals.', 'For over forty years we''ve furnished every kind of space across Patna and Bihar — homes, hotels, hospitals, schools and offices — measuring, supplying and installing with the same care, whether it''s a single bedroom or an entire hospital wing.', null, null, null, null, '[]'::jsonb, 1) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('products', 'intro', 'Products: intro', 'What we do', 'Everything your space needs.', 'Curtains, flooring, wallpaper, mattresses, rugs, furniture and more — every category measured, supplied and fitted by our own team. Filter by one of the five elements, or browse the full range.', null, null, null, null, '[]'::jsonb, 1) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('blog', 'intro', 'Blog: intro', 'Journal', 'Notes on furnishing a home you love.', 'Practical advice from four decades of furnishing homes and businesses in Patna — from choosing curtains for the summer heat to picking the right floor for a busy clinic.', null, null, null, null, '[]'::jsonb, 1) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('contact', 'intro', 'Contact: intro', 'Contact', 'Let''s talk about your space.', 'Tell us what you''re planning. We''ll visit, measure and suggest options that suit your space and your budget — then supply and fit it with our own team.', null, null, null, null, '[]'::jsonb, 1) on conflict (page, key) do update set label = excluded.label, eyebrow = excluded.eyebrow, heading = excluded.heading, body = excluded.body, image_url = excluded.image_url, image_alt = excluded.image_alt, cta_label = excluded.cta_label, cta_href = excluded.cta_href, items = excluded.items;

